typedef long long ll;

typedef struct {
    int a, b;
} Pair;

static int cmp_pair(const void *p1, const void *p2) {
    const Pair *x = (const Pair *)p1;
    const Pair *y = (const Pair *)p2;
    if (x->a != y->a) return x->a - y->a;
    return x->b - y->b;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *A = (int *)malloc((N + 1) * sizeof(int));
    int *B = (int *)malloc((N + 1) * sizeof(int));
    Pair *pts = (Pair *)malloc(N * sizeof(Pair));

    for (int i = 1; i <= N; i++) scanf("%d", &A[i]);
    for (int i = 1; i <= N; i++) scanf("%d", &B[i]);

    /* Basic necessary conditions for vertices 1 and 2 */
    if (A[1] != 0 || B[2] != 0 || A[2] != B[1] || A[2] <= 0) {
        printf("-1\n");
        free(A); free(B); free(pts);
        return 0;
    }

    int D = A[2]; /* distance between vertex 1 and vertex 2 */

    /* Check all vertices satisfy metric constraints relative to 1 and 2 */
    for (int i = 1; i <= N; i++) {
        if (A[i] < 0 || B[i] < 0) {
            printf("-1\n");
            free(A); free(B); free(pts);
            return 0;
        }
        if (A[i] + B[i] < D) {
            printf("-1\n");
            free(A); free(B); free(pts);
            return 0;
        }
        if (((A[i] + B[i] - D) & 1) != 0) {
            printf("-1\n");
            free(A); free(B); free(pts);
            return 0;
        }
        pts[i - 1].a = A[i];
        pts[i - 1].b = B[i];
    }

    /* Sort and ensure no duplicate (A,B) pairs:
       In any unweighted graph, if two vertices have same distances from 1 and 2,
       they can be identified without affecting these distances, so duplicates are unnecessary
       for the minimum-edge realization and impossible under the intended characterization. */
    qsort(pts, N, sizeof(Pair), cmp_pair);
    for (int i = 1; i < N; i++) {
        if (pts[i].a == pts[i - 1].a && pts[i].b == pts[i - 1].b) {
            printf("-1\n");
            free(A); free(B); free(pts);
            return 0;
        }
    }

    /* Count required backbone vertices on some shortest path from 1 to 2.
       Such vertices satisfy A+B=D, and for every x=0..D there must be exactly one with A=x,B=D-x. */
    int *onPath = (int *)calloc(D + 1, sizeof(int));
    for (int i = 1; i <= N; i++) {
        if (A[i] + B[i] == D) {
            if (A[i] < 0 || A[i] > D || B[i] != D - A[i]) {
                printf("-1\n");
                free(A); free(B); free(pts); free(onPath);
                return 0;
            }
            onPath[A[i]]++;
        }
    }
    for (int x = 0; x <= D; x++) {
        if (onPath[x] != 1) {
            printf("-1\n");
            free(A); free(B); free(pts); free(onPath);
            return 0;
        }
    }

    /* For off-path vertices, define:
       x = (A-B+D)/2  : attachment position on the 1-2 backbone
       y = (A+B-D)/2  : distance from backbone
       Need y>=1, and for each fixed x, every layer 1..maxY must exist (at least one vertex).
       Minimum edges:
         backbone: D
         for each x, layers contribute count(vertices at layer>=1) + (number of layers - 1)
       equivalently for each x: cnt_x + maxY_x - 1, if cnt_x>0
    */
    int *maxY = (int *)calloc(D + 1, sizeof(int));
    char **seen = (char **)malloc((D + 1) * sizeof(char *));
    for (int x = 0; x <= D; x++) seen[x] = NULL;

    for (int x = 0; x <= D; x++) {
        seen[x] = NULL;
    }

    /* First determine maxY per x */
    for (int i = 1; i <= N; i++) {
        int sum = A[i] + B[i];
        if (sum == D) continue;
        int x2 = A[i] - B[i] + D;
        if (x2 < 0 || (x2 & 1)) {
            printf("-1\n");
            for (int t = 0; t <= D; t++) free(seen[t]);
            free(seen); free(maxY); free(A); free(B); free(pts); free(onPath);
            return 0;
        }
        int x = x2 / 2;
        int y = (sum - D) / 2;
        if (x < 0 || x > D || y <= 0) {
            printf("-1\n");
            for (int t = 0; t <= D; t++) free(seen[t]);
            free(seen); free(maxY); free(A); free(B); free(pts); free(onPath);
            return 0;
        }
        if (y > maxY[x]) maxY[x] = y;
    }

    for (int x = 0; x <= D; x++) {
        if (maxY[x] > 0) {
            seen[x] = (char *)calloc(maxY[x] + 1, sizeof(char));
        }
    }

    ll ans = D; /* backbone edges */
    int *cnt = (int *)calloc(D + 1, sizeof(int));

    for (int i = 1; i <= N; i++) {
        int sum = A[i] + B[i];
        if (sum == D) continue;
        int x = (A[i] - B[i] + D) / 2;
        int y = (sum - D) / 2;
        cnt[x]++;
        seen[x][y] = 1;
    }

    for (int x = 0; x <= D; x++) {
        if (cnt[x] == 0) continue;
        for (int y = 1; y <= maxY[x]; y++) {
            if (!seen[x][y]) {
                printf("-1\n");
                for (int t = 0; t <= D; t++) free(seen[t]);
                free(seen); free(maxY); free(cnt); free(A); free(B); free(pts); free(onPath);
                return 0;
            }
        }
        ans += (ll)cnt[x] + (ll)maxY[x] - 1;
    }

    printf("%lld\n", ans);

    for (int t = 0; t <= D; t++) free(seen[t]);
    free(seen);
    free(maxY);
    free(cnt);
    free(A);
    free(B);
    free(pts);
    free(onPath);
    return 0;
}

