int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> A(N + 1), B(N + 1);
    for (int i = 1; i <= N; ++i) cin >> A[i];
    for (int i = 1; i <= N; ++i) cin >> B[i];

    // Basic necessary conditions for distances from 1 and 2
    if (A[1] != 0 || B[2] != 0 || A[2] != 1 || B[1] != 1) {
        cout << -1 << '\n';
        return 0;
    }

    // For every edge (u,v), |A[u]-A[v]|<=1 and |B[u]-B[v]|<=1.
    // Hence for every vertex i, |A[i]-B[i]| <= dist(1,2) = 1.
    for (int i = 1; i <= N; ++i) {
        if (llabs(A[i] - B[i]) > 1) {
            cout << -1 << '\n';
            return 0;
        }
    }

    // Classify vertices:
    // L_k : A=k, B=k+1
    // M_k : A=k, B=k
    // R_k : A=k+1, B=k
    //
    // Any valid vertex must be in exactly one of these forms.
    long long maxLevel = 0;
    map<long long, long long> cntL, cntM, cntR;

    for (int i = 1; i <= N; ++i) {
        if (B[i] == A[i] + 1) {
            cntL[A[i]]++;
            maxLevel = max(maxLevel, A[i]);
        } else if (A[i] == B[i]) {
            cntM[A[i]]++;
            maxLevel = max(maxLevel, A[i]);
        } else if (A[i] == B[i] + 1) {
            cntR[B[i]]++;
            maxLevel = max(maxLevel, B[i]);
        } else {
            cout << -1 << '\n';
            return 0;
        }
    }

    // Vertex 1 must be L_0, vertex 2 must be R_0
    if (cntL[0] != 1 || cntR[0] != 1) {
        cout << -1 << '\n';
        return 0;
    }
    // No M_0 because that would mean distance 0 from both 1 and 2
    if (cntM[0] != 0) {
        cout << -1 << '\n';
        return 0;
    }

    // Connectivity / existence conditions:
    // For every non-empty level k>0 among L_k, M_k, R_k,
    // there must be some vertex at level k-1 to connect from.
    // More precisely:
    // - L_k can only connect from L_{k-1} or M_{k-1}
    // - R_k can only connect from R_{k-1} or M_{k-1}
    // - M_k can only connect from L_{k-1}, M_{k-1}, or R_{k-1}
    //
    // Also, if M_k exists, then there must be at least 2 vertices in
    // previous total layer (L_{k-1}+M_{k-1}+R_{k-1}) for k=1? Actually for k=1,
    // previous layer has vertices 1 and 2, so fine. In general one is enough
    // for shortest path existence from both sides through same predecessor chain,
    // because distances are only constrained globally. Minimal edges just need
    // one incoming edge per new vertex.
    //
    // The minimal number of edges in any connected graph on N vertices is N-1.
    // If the constraints are realizable, we can always realize them by a tree:
    // connect each vertex to one suitable predecessor in previous layer.
    // So answer is N-1 whenever realizable.

    for (long long k = 1; k <= maxLevel; ++k) {
        long long prevL = cntL[k - 1];
        long long prevM = cntM[k - 1];
        long long prevR = cntR[k - 1];

        if (cntL[k] > 0 && prevL + prevM == 0) {
            cout << -1 << '\n';
            return 0;
        }
        if (cntR[k] > 0 && prevR + prevM == 0) {
            cout << -1 << '\n';
            return 0;
        }
        if (cntM[k] > 0 && prevL + prevM + prevR == 0) {
            cout << -1 << '\n';
            return 0;
        }
    }

    cout << (N - 1) << '\n';
    return 0;
}

